(function() {
  'use strict';

  // 初始化数据访问
  const paperMindData = window.paperMindData || {};
  const tables = paperMindData.tables || [];
  const sources = paperMindData.sources || {};

  // 查找 Table 1
  let table1Data = null;
  for (let i = 0; i < tables.length; i++) {
    if (tables[i].id === 'p6-Table_1') {
      table1Data = tables[i];
      break;
    }
  }

  //  DOM 元素
  const section = document.querySelector('.chapter-complexity-analysis');
  if (!section) return;

  const inputN = document.getElementById('complexity-n');
  const displayN = document.getElementById('complexity-n-display');
  const inputD = document.getElementById('complexity-d');
  const visualContainer = document.getElementById('complexity-values');
  const tableContent = document.getElementById('table-1-content');

  const barSA = document.getElementById('bar-sa');
  const barRNN = document.getElementById('bar-rnn');
  const bar3X = document.getElementById('bar-3x');

  // 渲染 Table 1 内容
  function renderTable1() {
    if (!table1Data || !tableContent) return;

    let html = '<table><thead><tr>';
    table1Data.columns.forEach(col => {
      html += `<th>${col}</th>`;
    });
    html += '</tr></thead><tbody>';

    table1Data.rows.forEach(row => {
      html += '<tr>';
      table1Data.columns.forEach(col => {
        const val = row.values[col] || '';
        // 简单处理 LaTeX 符号显示
        html += `<td>${val.replace(/\$/g, '')}</td>`;
      });
      html += '</tr>';
    });

    html += '</tbody></table>';
    tableContent.innerHTML = html;
  }

  // 计算与更新视觉
  function updateVisualization() {
    if (!inputN || !inputD || !visualContainer) return;

    const n = parseInt(inputN.value, 10);
    const d = parseInt(inputD.value, 10);

    if (isNaN(n) || isNaN(d)) return;

    // 更新显示
    if (displayN) displayN.textContent = n;

    // 计算理论值 (接受接口指定公式)
    // [n*n*d, n*d*d, 3*n*d*d]
    const valSA = n * n * d;
    const valRNN = n * d * d;
    const val3X = 3 * n * d * d;

    const values = [valSA, valRNN, val3X];

    // 同步 data-values 属性
    visualContainer.setAttribute('data-values', JSON.stringify(values));

    // 绘制条形图 (归一化)
    // 找到最大值作为基准，避免溢出
    const maxVal = Math.max(valSA, valRNN, val3X, 1);
    visualContainer.replaceChildren();
    ['自注意力 · n²d','循环层 · nd²','卷积示例 · 3nd²'].forEach((name,i)=>{
      const row=document.createElement('div');row.className='complexity-row';
      const label=document.createElement('span');label.textContent=name;
      const track=document.createElement('div');track.className='complexity-track';
      const bar=document.createElement('div');bar.dataset.complexityIndex=i;bar.style.width=(values[i]/maxVal*100)+'%';bar.className='complexity-bar complexity-'+i;track.append(bar);
      const value=document.createElement('output');value.textContent=values[i].toLocaleString();row.append(label,track,value);visualContainer.append(row);
    });
    // 更新顺序操作提示文本 (基于 n 与 d 关系)
    const seqOps = section.querySelector('.sequential-ops');
    if (seqOps) {
      const rnnOps = n > 1 ? `${n}（随 n 线性增长）` : 'O(1)';
      seqOps.innerHTML = `
        <span class="op-item">Self-Attention 顺序操作：<strong>O(1)</strong></span>
        <span class="op-item">Recurrent 顺序操作：<strong>${rnnOps}</strong></span>
      `;
    }
  }

  // 事件监听
  function initEvents() {
    if (inputN) {
      inputN.addEventListener('input', updateVisualization);
    }
    if (inputD) {
      inputD.addEventListener('change', updateVisualization);
    }

    // 来源按钮处理 (仅触发事件，不自行 postMessage)
    const sourceBtns = section.querySelectorAll('.btn-source');
    sourceBtns.forEach(btn => {
      btn.addEventListener('click', function() {
        // 宿主内核会处理 data-source 属性
      });
    });
  }

  // 初始化
  function init() {
    renderTable1();
    updateVisualization();
    initEvents();
  }

  // 执行
  try {
    init();
  } catch (e) {
    // 静默失败，不 alert 不 console
  }
})();
